119→/**
120→ * Generate page numbers array with ellipsis for pagination UI
121→ * @param currentPage - Current active page (1-based)
122→ * @param totalPages - Total number of pages
123→ * @param siblingCount - Number of siblings on each side of current page
124→ * @returns Array of page numbers and 'ellipsis' markers
125→ *
126→ * Examples:
127→ * - totalPages=10, currentPage=1 => [1, 2, 3, 4, 5, 'ellipsis', 10]
128→ * - totalPages=10, currentPage=5 => [1, 'ellipsis', 4, 5, 6, 'ellipsis', 10]
129→ * - totalPages=10, currentPage=10 => [1, 'ellipsis', 6, 7, 8, 9, 10]
130→ */
131→function generatePageNumbers(
132→  currentPage: number,
133→  totalPages: number,
134→  siblingCount: number = 1
135→): (number | 'ellipsis')[] {
136→  // Total page buttons: first + last + current + 2*siblings + 2*ellipsis = 7
137→  const totalPageNumbers = siblingCount * 2 + 5;
138→
139→  // Case 1: If total pages fit without ellipsis, show all
140→  if (totalPages <= totalPageNumbers) {
141→    return Array.from({ length: totalPages }, (_, i) => i + 1);
142→  }
143→
144→  const leftSiblingIndex = Math.max(currentPage - siblingCount, 1);
145→  const rightSiblingIndex = Math.min(currentPage + siblingCount, totalPages);
146→
147→  const showLeftEllipsis = leftSiblingIndex > 2;
148→  const showRightEllipsis = rightSiblingIndex < totalPages - 1;
149→
150→  // Case 2: Right ellipsis only (near start)
151→  if (!showLeftEllipsis && showRightEllipsis) {
152→    const leftRange = Array.from(
153→      { length: 3 + 2 * siblingCount },
154→      (_, i) => i + 1
155→    );
156→    return [...leftRange, 'ellipsis', totalPages];
157→  }
158→
159→  // Case 3: Left ellipsis only (near end)
160→  if (showLeftEllipsis && !showRightEllipsis) {
161→    const rightRange = Array.from(
162→      { length: 3 + 2 * siblingCount },
163→      (_, i) => totalPages - (3 + 2 * siblingCount) + i + 1
164→    );
165→    return [1, 'ellipsis', ...rightRange];
166→  }
167→
168→  // Case 4: Both ellipsis (in middle)
169→  const middleRange = Array.from(
170→    { length: rightSiblingIndex - leftSiblingIndex + 1 },
171→    (_, i) => leftSiblingIndex + i
172→  );
173→  return [1, 'ellipsis', ...middleRange, 'ellipsis', totalPages];
174→}
