  8→  PaginationLink,
  9→  PaginationNext,
 10→  PaginationPrevious,
 11→  generatePageNumbers,
 12→} from "@/components/ui/pagination";
 13→import { cn } from "@/lib/utils";
 14→
 15→interface DataTablePaginationProps {
 16→  /** Current page (1-based) */
 17→  page: number;
 18→  /** Total number of pages */
 19→  totalPages: number;
 20→  /** Total number of items */
 21→  total: number;
 22→  /** Number of items per page */
 23→  pageSize: number;
 24→  /** Callback when page changes */
 25→  onPageChange: (page: number) => void;
 26→  /** Whether to show info text (e.g., "총 1,234건 중 21 - 40") */
 27→  showInfo?: boolean;
 28→  /** Additional class name for container */
 29→  className?: string;
 30→}
 31→
 32→export function DataTablePagination({
 33→  page,
 34→  totalPages,
 35→  total,
 36→  pageSize,
 37→  onPageChange,
 38→  showInfo = true,
 39→  className,
 40→}: DataTablePaginationProps) {
 41→  const pageNumbers = generatePageNumbers(page, totalPages);
 42→
 43→  const startItem = total > 0 ? (page - 1) * pageSize + 1 : 0;
 44→  const endItem = Math.min(page * pageSize, total);
 45→
 46→  return (
 47→    <div className={cn("flex items-center justify-between", className)}>
 48→      {/* Info text */}
 49→      {showInfo && (
 50→        <div className="text-sm text-muted-foreground">
 51→          총 {total.toLocaleString()}건 중 {startItem.toLocaleString()} - {endItem.toLocaleString()}
 52→        </div>
 53→      )}
 54→
 55→      {/* Pagination controls */}
 56→      <Pagination className={cn(!showInfo && "mx-0")}>
 57→        <PaginationContent>
 58→          {/* Previous button */}
 59→          <PaginationItem>
 60→            <PaginationPrevious
 61→              onClick={() => page > 1 && onPageChange(page - 1)}
 62→              className={cn(
 63→                "cursor-pointer select-none",
 64→                page <= 1 && "pointer-events-none opacity-50"
 65→              )}
 66→            />
 67→          </PaginationItem>
 68→
 69→          {/* Page numbers */}
 70→          {pageNumbers.map((pageNum, idx) => (
 71→            <PaginationItem key={idx}>
 72→              {pageNum === "ellipsis" ? (
 73→                <PaginationEllipsis />
 74→              ) : (
 75→                <PaginationLink
 76→                  isActive={pageNum === page}
 77→                  onClick={() => onPageChange(pageNum)}
 78→                  className="cursor-pointer select-none"
 79→                >
 80→                  {pageNum}
 81→                </PaginationLink>
 82→              )}
 83→            </PaginationItem>
 84→          ))}
 85→
 86→          {/* Next button */}
 87→          <PaginationItem>
 88→            <PaginationNext
 89→              onClick={() => page < totalPages && onPageChange(page + 1)}
 90→              className={cn(
 91→                "cursor-pointer select-none",
 92→                page >= totalPages && "pointer-events-none opacity-50"
 93→              )}
 94→            />
 95→          </PaginationItem>
 96→        </PaginationContent>
 97→      </Pagination>
 98→    </div>
 99→  );
100→}
