import { NextConfig } from 'next'

const ENV_URLS = {
    // # 가격비교 GRAPHQL URL(카탈로그, 상품, 카테고리, 속성, 제조사/브랜드 등등)
    SHOPPING_URL: process.env.SHOPPING_URL,
    // # 회원 GRAPHQL URL(사용자, 권한, 메뉴 등등)
    AUTH_URL: process.env.GRAPHQL_AUTH_URL,
    // # AI 속성 감지 도구 API URL
    AI_ATTRIBUTE_URL: process.env.AI_ATTRIBUTE_URL
}

const API_PATHS = Object.entries(ENV_URLS).map(([key, url]) => {
    const source = `/${key.replace('_URL', '')}/:path*`
    return {
        source,
        destination: `${url}/:path*`
    }
})

// Place system REST API proxy rewrites (CORS bypass)
// Restricted to /api/* paths only to prevent SSRF on internal/actuator endpoints
const PLACE_REWRITES = [
    {
        source: '/place-api/api/:path*',
        destination: `${process.env.PLACE_API_URL || 'http://localhost:8081'}/api/:path*`
    }
]

// Billing system REST API proxy rewrites (CORS bypass)
// Backend URLs are server-side only (no NEXT_PUBLIC_ prefix)
const BILLING_REWRITES = [
    {
        source: '/billing-api/settlements/:path*',
        destination: `${process.env.SETTLEMENT_API_URL || 'http://localhost:8085'}/api/settlements/:path*`
    },
    {
        source: '/billing-api/admin/:path*',
        destination: `${process.env.ADMIN_API_URL || 'http://localhost:8086'}/api/admin/:path*`
    },
    {
        source: '/billing-api/payments/:path*',
        destination: `${process.env.PAYMENT_API_URL || 'http://localhost:8083'}/api/payments/:path*`
    },
    {
        source: '/billing-api/orders/:path*',
        destination: `${process.env.ORDER_API_URL || 'http://localhost:8082'}/api/orders/:path*`
    },
    {
        source: '/billing-api/carts/:path*',
        destination: `${process.env.CART_API_URL || 'http://localhost:8081'}/api/carts/:path*`
    },
    {
        source: '/billing-api/purchase-proxy/:path*',
        destination: `${process.env.PURCHASE_PROXY_API_URL || 'http://localhost:8098'}/api/purchase-proxy/:path*`
    },
    // INICIS PG checkout & callback proxy (PAYMENT_SERVER_BASE_URL points to admin domain)
    {
        source: '/api/payments/checkout/:path*',
        destination: `${process.env.PAYMENT_API_URL || 'http://localhost:8083'}/api/payments/checkout/:path*`
    },
    {
        source: '/api/payments/inicis/:path*',
        destination: `${process.env.PAYMENT_API_URL || 'http://localhost:8083'}/api/payments/inicis/:path*`
    }
]

const nextConfig: NextConfig = {
    reactStrictMode: true,
    output: 'standalone',
    async rewrites() {
        return [...API_PATHS, ...PLACE_REWRITES, ...BILLING_REWRITES]
    },
    async redirects() {
        return [
            {
                source: '/',
                destination: '/home',
                permanent: false
            }
        ]
    },
    images: {
        unoptimized: true
    }
}

export default nextConfig

// ──────────────────────────────────────────────
// Billing System REST API Client
// Routes through Next.js rewrites (/billing-api/*) to avoid CORS
// Backend URLs are configured server-side in next.config.ts
// ──────────────────────────────────────────────

const BILLING_PROXY_PATHS = {
    settlement: '/billing-api/settlements',
    admin: '/billing-api/admin',
    payment: '/billing-api/payments',
    order: '/billing-api/orders',
    cart: '/billing-api/carts',
    'purchase-proxy': '/billing-api/purchase-proxy'
} as const

export type BillingServiceName = keyof typeof BILLING_PROXY_PATHS

export class BillingApiError extends Error {
    status: number
    detail?: string

    constructor(status: number, message: string, detail?: string) {
        super(detail ?? message)
        this.name = 'BillingApiError'
        this.status = status
        this.detail = detail
    }
}

const createBillingError = async (response: Response): Promise<BillingApiError> => {
    let detail: string | undefined
    try {
        const body = await response.json()
        detail = body.message ?? body.error ?? JSON.stringify(body)
    } catch {
        detail = response.statusText
    }
    return new BillingApiError(response.status, `API Error (${response.status})`, detail)
}

interface RequestOptions extends Omit<RequestInit, 'body'> {
    body?: unknown
    params?: Record<string, string | number | boolean | undefined>
}

const buildUrl = (
    basePath: string,
    path: string,
    params?: Record<string, string | number | boolean | undefined>
): string => {
    const fullPath = path.startsWith('/') ? `${basePath}${path}` : `${basePath}/${path}`
    if (!params) return fullPath

    const searchParams = new URLSearchParams()
    Object.entries(params).forEach(([key, value]) => {
        if (value !== undefined) {
            searchParams.set(key, String(value))
        }
    })
    const qs = searchParams.toString()
    return qs ? `${fullPath}?${qs}` : fullPath
}

const billingFetch = async <T>(service: BillingServiceName, path: string, options: RequestOptions = {}): Promise<T> => {
    const basePath = BILLING_PROXY_PATHS[service]
    const { body, params, headers, ...restOptions } = options

    const url = buildUrl(basePath, path, params)

    const response = await fetch(url, {
        ...restOptions,
        headers: {
            'Content-Type': 'application/json',
            ...headers
        },
        ...(body !== undefined ? { body: JSON.stringify(body) } : {})
    })

    if (!response.ok) {
        throw await createBillingError(response)
    }

    if (response.status === 204) {
        return undefined as T
    }

    return response.json()
}

export const billingApi = {
    get: <T>(
        service: BillingServiceName,
        path: string,
        params?: Record<string, string | number | boolean | undefined>
    ) => billingFetch<T>(service, path, { method: 'GET', params }),

    post: <T>(service: BillingServiceName, path: string, body?: unknown) =>
        billingFetch<T>(service, path, { method: 'POST', body }),

    put: <T>(service: BillingServiceName, path: string, body?: unknown) =>
        billingFetch<T>(service, path, { method: 'PUT', body }),

    patch: <T>(service: BillingServiceName, path: string, body?: unknown) =>
        billingFetch<T>(service, path, { method: 'PATCH', body }),

    delete: <T>(service: BillingServiceName, path: string, body?: unknown) =>
        billingFetch<T>(service, path, { method: 'DELETE', body })
} as const

// middleware.ts
import { NextRequest, NextResponse } from 'next/server'
import {
    MOCK_ENABLED,
    GRAPHQL_ENDPOINT,
    isUnauthorizedPostRequest,
    handleMockTokens,
    validateTokens,
    extractTokens,
    checkPermission
} from '@/shared/services/middleware'

export async function middleware(req: NextRequest) {
    // 1) Mock 서버 모드면 mock 토큰 설정 후 통과
    if (MOCK_ENABLED) {
        return handleMockTokens(req)
    }

    // 2) unauthorized 페이지로의 POST 요청 차단
    if (isUnauthorizedPostRequest(req.nextUrl.pathname, req.method)) {
        return new NextResponse('Method Not Allowed', { status: 405 })
    }

    // 3) 토큰 검증 (access_token, refresh_token)
    const tokenValidationResult = validateTokens(req)
    if (tokenValidationResult) {
        return tokenValidationResult
    }

    // 4) 권한 체크 (도메인·경로 기반)
    try {
        const { access_token } = extractTokens(req)
        return await checkPermission(req, access_token, GRAPHQL_ENDPOINT)
    } catch (error) {
        // 토큰 추출 실패 시 로그인 페이지로 리다이렉트
        console.error('Token extraction failed:', error)
        return NextResponse.redirect(new URL('/login', req.url))
    }
}

export const config = {
    matcher: [
        /*
         * Match all request paths except for the ones starting with:
         * - api (API routes)
         * - _next/static (static files)
         * - _next/image (image optimization files)
         * - favicon.ico (favicon file)
         * - .well-known (browser auto-requests)
         * - AUTH (GraphQL proxy endpoint)
         */
        '/((?!api|billing-api|_next/static|_next/image|favicon.ico|\\.well-known|login|unauthorized|error|auth|popup|AUTH|SHOPPING|AI_ATTRIBUTE).*)'
    ]
}

