// ========================================
// Dictionary Types
// ========================================

// 8개 사전 타입 정의
export type DictionaryType =
    | 'STOP'        // SET: 불용어
    | 'USER'        // SET: 사용자 정의 단어
    | 'ENGLISH'     // SET: 영문 단어
    | 'UNIT'        // SET: 단위
    | 'SYNONYM'     // SYNONYM: 동의어 (양방향/단방향)
    | 'UNIT_SYNONYM'// SYNONYM: 단위 동의어
    | 'SPACE'       // MAP: 공백 분리
    | 'COMPOUND';   // MAP: 복합어 분해

// 데이터 구조 카테고리
export type DictionaryCategory = 'SET' | 'SYNONYM' | 'MAP';

// 카테고리별 타입 매핑
export const DICTIONARY_CATEGORY_MAP: Record<DictionaryType, DictionaryCategory> = {
    STOP: 'SET',
    USER: 'SET',
    ENGLISH: 'SET',
    UNIT: 'SET',
    SYNONYM: 'SYNONYM',
    UNIT_SYNONYM: 'SYNONYM',
    SPACE: 'MAP',
    COMPOUND: 'MAP',
};

// 사전 타입별 레이블
export const DICTIONARY_TYPE_LABELS: Record<DictionaryType, string> = {
    STOP: '불용어',
    USER: '사용자 단어',
    ENGLISH: '영문 단어',
    UNIT: '단위',
    SYNONYM: '동의어',
    UNIT_SYNONYM: '단위 동의어',
    SPACE: '공백 분리',
    COMPOUND: '복합어',
};

// 사전 타입별 전체 이름 (개요 테이블용)
export const DICTIONARY_NAMES: Record<DictionaryType, string> = {
    STOP: '불용어 사전',
    USER: '사용자 사전',
    ENGLISH: '영단어 사전',
    UNIT: '단위명 사전',
    SYNONYM: '동의어 사전',
    UNIT_SYNONYM: '단위명동의어 사전',
    SPACE: '분리어 사전',
    COMPOUND: '복합명사 사전',
};

// 사전 메뉴 섹션 타입 (개요 + 각 사전 타입)
export type MenuSection = 'OVERVIEW' | DictionaryType;

// ========================================
// Dictionary Overview Types
// ========================================

export interface DictionaryOverviewItem {
    type: DictionaryType;
    count: number;
    lastModified: string | null;
}

export interface DictionaryOverviewResponse {
    items: DictionaryOverviewItem[];
}

export interface Dictionary {
    id: string;
    type: DictionaryType;
    keyword: string | null;  // null for bidirectional synonym
    value: string;
    createdAt?: string;
    updatedAt?: string;
}

// SYNONYM 전용: 양방향/단방향 구분
export interface SynonymDictionary extends Dictionary {
    type: 'SYNONYM' | 'UNIT_SYNONYM';
    direction: 'bidirectional' | 'unidirectional';
}

export interface DictionarySummaryItem {
    type: DictionaryType;
    name: string;
    count: number;
    modifiedTime?: string;
    appliedCount?: number;
    appliedTime?: string;
    tokenType?: string;
    ignoreCase?: boolean;
    compiled: boolean;
    hasChanges: boolean;
}

export interface DictionaryCompileStatus {
    type: DictionaryType;
    status: 'COMPILED' | 'PENDING' | 'ERROR';
    lastCompiled?: string;
    message?: string;
}

export interface AnalysisResult {
    tokens: AnalysisToken[];
}

export interface AnalysisToken {
    token: string;
    start_offset: number;
    end_offset: number;
    type: string;
    position: number;
}

export interface DetailAnalysisResult {
    index: string;
    field: string;
    content: string;
    analyzed: string;
}

export interface SavedQuery {
    id: string;
    name: string;
    index: string;
    query: string;
    createdAt: string;
}

// ========================================
// Search Types
// ========================================

export interface SearchTemplate {
    id: string;
    name: string;
    indices: string;
    query: string;
    title: string;
    clickUrl: string;
    thumbnails: string;
    order: number;
    fields: Array<{ label: string; value: string }>;
    aggs: Array<{ label: string; value: string }>;
}

export interface ReferenceUIConfig {
    autocompleteUrl?: string;
    templates: SearchTemplate[];
}

// ========================================
// Management Types
// ========================================

export interface JDBCSource {
    id: string;
    name: string;
    driver: string;
    driverClass: string;
    url: string;
    host: string;
    port: string;
    database: string;
    user: string;
    password: string;
    jdbcParams?: string;
}

export interface Pipeline {
    id: string;
    description?: string;
    processors: PipelineProcessor[];
}

export interface PipelineProcessor {
    [type: string]: {
        field?: string;
        value?: string;
        pattern?: string;
        replacement?: string;
        separator?: string;
        source?: string;
        target_field?: string;
        ignore_failure?: boolean;
        [key: string]: unknown;
    };
}

export interface Scheduler {
    id: string;
    name: string;
    cron: string;
    collectionId: string;
    collectionName?: string;
    enabled: boolean;
    status: 'RUNNING' | 'STOPPED' | 'IDLE';
    lastRun?: string;
    nextRun?: string;
}

// ========================================
// Shard Types
// ========================================

export interface Shard {
    index: string;
    shard: string;
    prirep: 'p' | 'r';
    state: 'STARTED' | 'RELOCATING' | 'INITIALIZING' | 'UNASSIGNED';
    docs?: string;
    store?: string;
    ip?: string;
    node?: string;
}

// ========================================
// API Response Types
// ========================================

export interface ApiResponse<T> {
    success: boolean;
    data?: T;
    error?: string;
    message?: string;
}

export interface PaginatedResponse<T> {
    items: T[];
    total: number;
    page: number;
    pageSize: number;
    totalPages: number;
}

// ========================================
// UI State Types
// ========================================

export interface TableColumn<T> {
    key: keyof T | string;
    label: string;
    sortable?: boolean;
    width?: string;
    render?: (value: unknown, item: T) => React.ReactNode;
}

export interface SortConfig {
    key: string;
    direction: 'asc' | 'desc';
}

export interface FilterConfig {
    field: string;
    value: string;
    operator: 'eq' | 'contains' | 'gt' | 'lt';
}

// ========================================
// Re-export Dictionary Backend Types
// ========================================

export type {
    BackendDictionary,
    DictionaryWithId,  // @deprecated - use BackendDictionary
    CompileResult,
    CreateDictionaryRequest,
    UpdateDictionaryRequest,
    BackendPagedResponse,
    BackendCursorResponse,
} from './dictionary';

export {DICTIONARY_API} from './dictionary';

// ========================================
// Cursor-based Pagination Types
// ========================================

export interface CursorPaginatedResponse<T> {
    items: T[];
    total: number;
    nextCursor: string | null;
    hasNext: boolean;
}

