import type {DictionaryType} from './index';

// ========================================
// Backend Response DTOs
// ========================================

/**
 * Backend response for a single dictionary entry (flat structure)
 * Matches Spring Boot Dictionary entity returned by CursorPagedResponse
 */
export interface BackendDictionary {
    id: string;
    keyword: string | null;
    type: DictionaryType;
    value: string | null;
    createdTime: string; // ISO 8601 timestamp
    updatedTime: string; // ISO 8601 timestamp
}

/**
 * @deprecated Use BackendDictionary instead - kept for backward compatibility
 */
export type DictionaryWithId = BackendDictionary;

/**
 * Backend response for dictionary compilation
 * Matches Spring Boot CompileResult response
 */
export interface CompileResult {
    type: DictionaryType;
    count: number;
    filePath: string;
    fileSize: number;
}

// ========================================
// Backend Request DTOs
// ========================================

/**
 * Request body for creating a new dictionary entry
 * POST /api/v1/dictionary
 */
export interface CreateDictionaryRequest {
    keyword?: string | null;
    type: DictionaryType;
    value?: string | null;
}

/**
 * Request body for updating a dictionary entry
 * PUT /api/v1/dictionary/{id}
 */
export interface UpdateDictionaryRequest {
    keyword: string;
    type: DictionaryType;
    value?: string | null;
}

// ========================================
// API Path Constants
// ========================================

export const DICTIONARY_API = {
    BASE: '/api/v1/dictionary',
    list: (type: DictionaryType) => `/api/v1/dictionary/${type}`,
    search: (type: DictionaryType) => `/api/v1/dictionary/${type}/search`,
    create: () => '/api/v1/dictionary',
    update: (id: string) => `/api/v1/dictionary/${id}`,
    delete: (id: string) => `/api/v1/dictionary/${id}`,
    compile: () => '/api/v1/dictionary/compile',
    compileType: (type: DictionaryType) => `/api/v1/dictionary/compile/${type}`,
} as const;

/**
 * Backend paginated response format
 * Matches Spring Boot PagedResponse<Dictionary>
 */
export interface BackendPagedResponse {
    items: BackendDictionary[];
    total: number;
    page: number;
    size: number;
    totalPages: number;
}

/**
 * Backend cursor-based paginated response format
 * Matches Spring Boot CursorPagedResponse<Dictionary>
 */
export interface BackendCursorResponse {
    items: BackendDictionary[];
    total: number;
    cursor: string | null;  // Backend uses 'cursor', not 'nextCursor'
    hasNext: boolean;
}

import type {
    BackendCursorResponse,
    BackendDictionary,
    BackendPagedResponse,
    CursorPaginatedResponse,
    Dictionary,
    PaginatedResponse
} from '@/types';

/**
 * Transform backend BackendDictionary (flat structure) to frontend Dictionary model
 */
export function mapDictionaryResponse(data: BackendDictionary): Dictionary {
    return {
        id: data.id,
        type: data.type,
        keyword: data.keyword,
        value: data.value ?? '',
        createdAt: data.createdTime,
        updatedAt: data.updatedTime,
    };
}

/**
 * Transform backend PagedResponse to frontend PaginatedResponse
 * Uses the total count from backend for accurate pagination
 */
export function mapPagedDictionaryResponse(
    data: BackendPagedResponse,
    requestedPage: number,
    pageSize: number
): PaginatedResponse<Dictionary> {
    return {
        items: data.items.map(mapDictionaryResponse),
        total: data.total,
        page: requestedPage,
        pageSize,
        totalPages: data.totalPages,
    };
}

/**
 * Transform array of backend responses to paginated frontend response
 * Used for search results that return arrays without pagination metadata
 */
export function mapDictionaryListResponse(
    data: BackendDictionary[],
    page: number,
    pageSize: number
): PaginatedResponse<Dictionary> {
    return {
        items: data.map(mapDictionaryResponse),
        total: data.length,
        page,
        pageSize,
        totalPages: Math.max(1, Math.ceil(data.length / pageSize)),
    };
}

/**
 * Transform backend CursorPagedResponse to frontend CursorPaginatedResponse
 * Used for cursor-based pagination that avoids ES from+size limit
 * Note: Backend uses 'cursor', frontend uses 'nextCursor'
 */
export function mapCursorDictionaryResponse(
    data: BackendCursorResponse
): CursorPaginatedResponse<Dictionary> {
    return {
        items: data.items.map(mapDictionaryResponse),
        total: data.total,
        nextCursor: data.cursor,  // Map backend 'cursor' to frontend 'nextCursor'
        hasNext: data.hasNext,
    };
}

