 37→import {useDeleteDictionary, useDictionaries, type SortType} from "@/hooks/use-dictionary";
 38→import type {Dictionary, DictionaryType} from "@/types";
 39→import {DICTIONARY_CATEGORY_MAP} from "@/types";
 40→import {toast} from "sonner";
 41→
 42→interface DictionaryListProps {
 43→    type: DictionaryType;
 44→}
 45→
 46→export function DictionaryList({type}: DictionaryListProps) {
 47→    const [isEditMode, setIsEditMode] = useState(false);
 48→    const [selectedRows, setSelectedRows] = useState<string[]>([]);
 49→    const [addDialogOpen, setAddDialogOpen] = useState(false);
