 57→    const [wordMatch, setWordMatch] = useState(false);
 58→    const [pageSize] = useState(20);
 59→    const [sortType, setSortType] = useState<SortType>('UPDATED');
 60→
 61→    // Cursor-based pagination state
 62→    const [currentCursor, setCurrentCursor] = useState<string | null>(null);
 63→    const [cursorHistory, setCursorHistory] = useState<(string | null)[]>([null]); // Stack of cursors for "previous" navigation
 64→    const [currentPage, setCurrentPage] = useState(1); // For display purposes only
 65→
 66→    // Active search (only updates on Enter or button click)
 67→    const [activeSearch, setActiveSearch] = useState("");
 68→
 69→    const category = DICTIONARY_CATEGORY_MAP[type];
 70→
 71→    // API hooks
 72→    const {data, isLoading, isError, refetch} = useDictionaries({
 73→        type,
 74→        cursor: currentCursor,
 75→        pageSize,
 76→        search: activeSearch || undefined,
 77→        searchField,
 78→        wordMatch,
 79→        sortType,
 80→    });
 81→
 82→    const deleteMutation = useDeleteDictionary();
 83→
 84→    const items = data?.items || [];
 85→    const total = data?.total || 0;
 86→    const hasNext = data?.hasNext || false;
 87→    const nextCursor = data?.nextCursor || null;
 88→    const hasPrevious = cursorHistory.length > 1;
 89→
 90→    // Reset to first page
 91→    const resetPagination = () => {
 92→        setCurrentCursor(null);
 93→        setCursorHistory([null]);
 94→        setCurrentPage(1);
 95→    };
 96→
 97→    const handleSearch = () => {
 98→        resetPagination();
 99→        setActiveSearch(searchValue);
100→    };
101→
102→    const handleSortChange = (newSortType: SortType) => {
103→        if (newSortType !== sortType) {
104→            resetPagination();
105→            setSortType(newSortType);
106→        }
107→    };
108→
109→    const handleKeyDown = (e: React.KeyboardEvent) => {
110→        if (e.key === 'Enter') {
111→            handleSearch();
112→        }
113→    };
114→
115→    // Navigate to next page
116→    const handleNextPage = () => {
117→        if (hasNext && nextCursor) {
118→            setCursorHistory((prev) => [...prev, nextCursor]);
119→            setCurrentCursor(nextCursor);
120→            setCurrentPage((prev) => prev + 1);
121→        }
122→    };
123→
124→    // Navigate to previous page
125→    const handlePreviousPage = () => {
126→        if (hasPrevious) {
127→            const newHistory = [...cursorHistory];
128→            newHistory.pop(); // Remove current cursor
129→            const previousCursor = newHistory[newHistory.length - 1];
130→            setCursorHistory(newHistory);
131→            setCurrentCursor(previousCursor);
132→            setCurrentPage((prev) => Math.max(1, prev - 1));
133→        }
134→    };
135→
136→    // Navigate to first page
137→    const handleFirstPage = () => {
138→        resetPagination();
139→    };
140→
141→    const toggleSelectAll = (checked: boolean) => {
142→        if (checked) {
143→            setSelectedRows(items.map((row) => row.id));
144→        } else {
145→            setSelectedRows([]);
146→        }
147→    };
148→
149→    const toggleSelectRow = (id: string, checked: boolean) => {
150→        if (checked) {
151→            setSelectedRows((prev) => [...prev, id]);
152→        } else {
153→            setSelectedRows((prev) => prev.filter((rowId) => rowId !== id));
154→        }
155→    };
156→
157→    const handleEdit = (item: Dictionary) => {
158→        setEditingItem(item);
159→        setEditDialogOpen(true);
160→    };
161→
162→    const handleDeleteSelected = async () => {
163→        try {
164→            await deleteMutation.mutateAsync({type, ids: selectedRows});
165→            setSelectedRows([]);
166→            setDeleteDialogOpen(false);
167→            toast.success(`${selectedRows.length}개 항목이 삭제되었습니다.`);
168→        } catch (error) {
169→            toast.error('삭제 중 오류가 발생했습니다.');
170→        }
171→    };
172→
173→    // Determine if this is a SYNONYM type to show direction
174→    const isSynonymType = category === 'SYNONYM';
175→    const isSetType = category === 'SET';
176→    const isSpaceType = type === 'SPACE';
177→    const isCompoundType = type === 'COMPOUND';
178→
179→    // Get direction from dictionary item (bidirectional if keyword is null or empty string)
180→    const getDirection = (item: Dictionary) => {
181→        return item.keyword === null || item.keyword === '' ? 'bidirectional' : 'unidirectional';
182→    };
183→
184→    // Render value as badges
