206→                        </SelectTrigger>
207→                        <SelectContent>
208→                            <SelectItem value="all">전체</SelectItem>
209→                            {!isSetType && <SelectItem value="keyword">Keyword</SelectItem>}
210→                            <SelectItem value="value">{isSetType ? '단어' : 'Value'}</SelectItem>
211→                        </SelectContent>
