                                        &quot;5 {keyword}&quot; 검색 → &quot;5 {value}&quot;로 인식
                                    </p>
                                </div>
                            )}
                        </>
                    )}

                    {/* MAP Type Form (SPACE, COMPOUND) */}
                    {category === 'MAP' && (
                        <>
                            <div className="space-y-2">
                                <Label htmlFor="keyword">
                                    {type === 'SPACE' ? '붙여쓴 말' : '복합어'} *
                                </Label>
                                <Input
                                    id="keyword"
                                    value={keyword}
                                    onChange={(e) => setKeyword(e.target.value)}
                                    placeholder={type === 'SPACE' ? "삼성전자" : "고무장갑"}
                                />
                                {type === 'SPACE' && (
                                    <p className="text-xs text-muted-foreground">
                                        <Info className="inline h-3 w-3 mr-1"/>
