}

// ========================================
// Edit Dictionary Dialog
// ========================================

interface EditDictionaryDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    type: DictionaryType;
    item: Dictionary | null;
}

export function EditDictionaryDialog({open, onOpenChange, type, item}: EditDictionaryDialogProps) {
    const category = getCategory(type);
    const updateMutation = useUpdateDictionary();

    // Form state
    const [keyword, setKeyword] = useState("");
    const [value, setValue] = useState("");
    const [synonymDirection, setSynonymDirection] = useState<'bidirectional' | 'unidirectional'>('bidirectional');

    // Validation
    const [errors, setErrors] = useState<string[]>([]);

    // Initialize form when item changes
    useEffect(() => {
        if (item) {
            setKeyword(item.keyword || "");
            // SET types store word in keyword field, other types use value
            if (category === 'SET') {
                setValue(item.keyword || "");
            } else {
                setValue(item.value || "");
            }
            setSynonymDirection(item.keyword === null ? 'bidirectional' : 'unidirectional');
            setErrors([]);
        }
    }, [item, category]);

    const validate = (): boolean => {
        const newErrors: string[] = [];

        if (category === 'SET') {
            if (!value.trim()) {
                newErrors.push("단어를 입력해주세요.");
            }
        } else if (category === 'SYNONYM') {
            if (type === 'SYNONYM') {
                if (synonymDirection === 'bidirectional') {
                    const synonyms = parseCommaSeparated(value);
                    if (synonyms.length < 2) {
                        newErrors.push("양방향 동의어는 최소 2개 이상 입력해주세요.");
                    }
                } else {
                    if (!keyword.trim()) {
                        newErrors.push("대표 단어를 입력해주세요.");
                    }
                    if (!value.trim()) {
                        newErrors.push("동의어 목록을 입력해주세요.");
                    }
                    const synonyms = parseCommaSeparated(value);
                    if (synonyms.includes(keyword.trim())) {
                        newErrors.push("대표 단어가 동의어 목록에 포함될 수 없습니다.");
                    }
                }
            } else {
                if (!keyword.trim()) {
                    newErrors.push("대상 표현을 입력해주세요.");
                }
                if (!value.trim()) {
                    newErrors.push("정규화 기호를 입력해주세요.");
                }
            }
        } else if (category === 'MAP') {
            if (!keyword.trim()) {
                newErrors.push(type === 'SPACE' ? "붙여쓴 말을 입력해주세요." : "복합어를 입력해주세요.");
            }
            if (type === 'SPACE' && keyword.includes(' ')) {
                newErrors.push("붙여쓴 말에는 공백이 포함될 수 없습니다.");
            }
            if (!value.trim()) {
                newErrors.push(type === 'SPACE' ? "분리 결과를 입력해주세요." : "분해 결과를 입력해주세요.");
            }
            const parts = parseCommaSeparated(value);
            if (parts.length < 2) {
                newErrors.push("결과는 최소 2개 이상의 단어여야 합니다.");
            }
        }

        setErrors(newErrors);
        return newErrors.length === 0;
    };

    const handleSubmit = async () => {
        if (!item || !validate()) return;

        try {
            let finalKeyword: string | null = null;
            let finalValue: string | null = null;

            if (category === 'SET') {
                // SET types (STOP, USER, ENGLISH, UNIT) store word in keyword field
                finalKeyword = value.trim();
                finalValue = null;
            } else if (category === 'SYNONYM') {
                if (type === 'SYNONYM' && synonymDirection === 'bidirectional') {
                    finalKeyword = null;
                } else {
                    finalKeyword = keyword.trim();
                }
                finalValue = value.trim();
            } else if (category === 'MAP') {
                finalKeyword = keyword.trim();
                finalValue = value.trim();
            }

            await updateMutation.mutateAsync({
                type,
                id: item.id,
                keyword: finalKeyword,
                value: finalValue,
            });

            toast.success("사전이 수정되었습니다.");
            onOpenChange(false);
        } catch (error) {
            toast.error("수정 중 오류가 발생했습니다.");
        }
    };

    if (!item) return null;

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[500px]">
                <DialogHeader>
                    <DialogTitle>{getTypeLabel(type)} 사전 수정</DialogTitle>
                    <DialogDescription>
                        기존 {getTypeLabel(type)} 항목을 수정합니다.
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-4 py-4">
                    {/* SET Type Form */}
                    {category === 'SET' && (
                        <div className="space-y-2">
                            <Label htmlFor="value">단어 *</Label>
                            <Input
                                id="value"
                                value={value}
                                onChange={(e) => setValue(e.target.value)}
                            />
                        </div>
                    )}

                    {/* SYNONYM Type Form */}
                    {type === 'SYNONYM' && (
                        <>
                            <div className="space-y-3">
                                <Label>매핑 방향</Label>
                                <RadioGroup
                                    value={synonymDirection}
                                    onValueChange={(v) => setSynonymDirection(v as 'bidirectional' | 'unidirectional')}
                                    className="flex flex-col space-y-2"
                                >
                                    <div className="flex items-center space-x-2">
                                        <RadioGroupItem value="bidirectional" id="edit-bidirectional"/>
                                        <Label htmlFor="edit-bidirectional"
                                               className="font-normal flex items-center gap-2">
                                            <ArrowLeftRight className="h-4 w-4 text-blue-500"/>
                                            양방향 (상호 동의어)
                                        </Label>
                                    </div>
                                    <div className="flex items-center space-x-2">
                                        <RadioGroupItem value="unidirectional" id="edit-unidirectional"/>
                                        <Label htmlFor="edit-unidirectional"
                                               className="font-normal flex items-center gap-2">
                                            <ArrowRight className="h-4 w-4 text-green-500"/>
                                            단방향 (대표어 → 동의어)
                                        </Label>
                                    </div>
                                </RadioGroup>
                            </div>

                            <Separator/>

                            {synonymDirection === 'bidirectional' ? (
                                <div className="space-y-2">
                                    <Label htmlFor="edit-synonyms">동의어 그룹 *</Label>
                                    <Input
                                        id="edit-synonyms"
                                        value={value}
                                        onChange={(e) => setValue(e.target.value)}
                                    />
                                </div>
                            ) : (
                                <>
                                    <div className="space-y-2">
                                        <Label htmlFor="edit-keyword">대표 단어 *</Label>
                                        <Input
                                            id="edit-keyword"
                                            value={keyword}
                                            onChange={(e) => setKeyword(e.target.value)}
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <Label htmlFor="edit-synonymValue">동의어 목록 *</Label>
                                        <Input
                                            id="edit-synonymValue"
                                            value={value}
                                            onChange={(e) => setValue(e.target.value)}
                                        />
                                    </div>
                                </>
                            )}

                            <SynonymPreview
                                direction={synonymDirection}
                                keyword={keyword}
                                value={value}
                            />
                        </>
                    )}

                    {/* UNIT_SYNONYM Type Form */}
                    {type === 'UNIT_SYNONYM' && (
                        <>
                            <div className="space-y-2">
                                <Label htmlFor="edit-unit-keyword">대상 표현 *</Label>
                                <Input
                                    id="edit-unit-keyword"
                                    value={keyword}
                                    onChange={(e) => setKeyword(e.target.value)}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="edit-unit-value">정규화 기호 *</Label>
                                <Input
                                    id="edit-unit-value"
                                    value={value}
                                    onChange={(e) => setValue(e.target.value)}
                                />
                            </div>
                        </>
                    )}

                    {/* MAP Type Form */}
                    {category === 'MAP' && (
                        <>
                            <div className="space-y-2">
                                <Label htmlFor="edit-map-keyword">
                                    {type === 'SPACE' ? '붙여쓴 말' : '복합어'} *
                                </Label>
                                <Input
                                    id="edit-map-keyword"
                                    value={keyword}
                                    onChange={(e) => setKeyword(e.target.value)}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="edit-map-value">
                                    {type === 'SPACE' ? '분리 결과' : '분해 결과'} *
                                </Label>
                                <Input
                                    id="edit-map-value"
                                    value={value}
                                    onChange={(e) => setValue(e.target.value)}
                                />
                            </div>

                            <MapPreview type={type} keyword={keyword} value={value}/>
                        </>
                    )}

                    {/* Validation Errors */}
                    {errors.length > 0 && (
                        <Alert variant="destructive">
                            <AlertCircle className="h-4 w-4"/>
                            <AlertDescription>
                                <ul className="list-disc list-inside">
                                    {errors.map((error, i) => (
                                        <li key={i}>{error}</li>
                                    ))}
                                </ul>
                            </AlertDescription>
                        </Alert>
                    )}
                </div>

                <DialogFooter>
                    <Button variant="outline" onClick={() => onOpenChange(false)}>
                        취소
                    </Button>
                    <Button onClick={handleSubmit} disabled={updateMutation.isPending}>
                        {updateMutation.isPending && (
                            <Loader2 className="mr-2 h-4 w-4 animate-spin"/>
                        )}
                        저장
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

// ──────────────────────────────────────────────
// Place System REST API Client
// Routes through Next.js rewrites (/place-api/*) to avoid CORS
// Backend URL configured server-side in next.config.ts
// ──────────────────────────────────────────────

const PLACE_BASE_PATH = '/place-api/api'

export class PlaceApiError extends Error {
    status: number
    detail?: string

    constructor(status: number, message: string, detail?: string) {
        super(detail ?? message)
        this.name = 'PlaceApiError'
        this.status = status
        this.detail = detail
    }
}

const createPlaceError = async (response: Response): Promise<PlaceApiError> => {
    let detail: string | undefined
    try {
        const body = await response.json()
        detail = body.message ?? body.error ?? JSON.stringify(body)
    } catch {
        detail = response.statusText
    }
    return new PlaceApiError(response.status, `API Error (${response.status})`, detail)
}

interface RequestOptions extends Omit<RequestInit, 'body'> {
    body?: unknown
    params?: Record<string, string | number | boolean | undefined>
}

const buildUrl = (path: string, params?: Record<string, string | number | boolean | undefined>): string => {
    const fullPath = path.startsWith('/') ? `${PLACE_BASE_PATH}${path}` : `${PLACE_BASE_PATH}/${path}`
    if (!params) return fullPath

    const searchParams = new URLSearchParams()
    Object.entries(params).forEach(([key, value]) => {
        if (value !== undefined) {
            searchParams.set(key, String(value))
        }
    })
    const qs = searchParams.toString()
    return qs ? `${fullPath}?${qs}` : fullPath
}

const placeFetch = async <T>(path: string, options: RequestOptions = {}): Promise<T> => {
    const { body, params, headers, ...restOptions } = options

    const url = buildUrl(path, params)

    const response = await fetch(url, {
        ...restOptions,
        headers: {
            'Content-Type': 'application/json',
            ...headers
        },
        ...(body !== undefined ? { body: JSON.stringify(body) } : {})
    })

    if (!response.ok) {
        throw await createPlaceError(response)
    }

    if (response.status === 204) {
        return undefined as T
    }

    return response.json()
}

export const placeApi = {
    get: <T>(path: string, params?: Record<string, string | number | boolean | undefined>) =>
        placeFetch<T>(path, { method: 'GET', params }),

    post: <T>(path: string, body?: unknown) => placeFetch<T>(path, { method: 'POST', body }),

    put: <T>(path: string, body?: unknown) => placeFetch<T>(path, { method: 'PUT', body }),

    patch: <T>(path: string, body?: unknown) => placeFetch<T>(path, { method: 'PATCH', body }),

    delete: <T>(path: string, body?: unknown) => placeFetch<T>(path, { method: 'DELETE', body })
} as const

import { Button, Modal } from 'antd'
import { useDictionaryManagement } from '@/views/dictionary-manage/model/useDictionaryManagement'
import { DictionaryManageSearchCondition } from '@/views/dictionary-manage/ui/DictionaryManageSearchCondition'
import { DictionaryManageTable } from '@/views/dictionary-manage/ui/DictionaryManageTable'
import { DictionaryPreviewPanel } from '@/views/dictionary-manage/ui/DictionaryPreviewPanel'

export const DictionaryManagePage = () => {
    const {
        dictionaries,
        totalCount,
        loading,
        selectedRowKeys,
        currentPage,
        pageSize,
        selectedItem,
        handleSearchChange,
        handlePageChange,
        handleAdd,
        handleEdit,
        handleDelete,
        setSelectedRowKeys,
        handleItemClick,
        handleCloseDetail
    } = useDictionaryManagement()

    return (
        <div className="flex h-full gap-3 p-4">
            {/* 메인 콘텐츠 영역 */}
            <div className="flex flex-1 flex-col gap-3">
                <div className="flex h-full flex-col gap-4 p-3">
                    {/* 검색 조건 */}
                    <DictionaryManageSearchCondition onSearchChange={handleSearchChange} showSwitch={false} />
                    {/* 액션 버튼 */}
                    <div className="flex items-center justify-between">
                        <div className="text-sm text-gray-600">
                            총 {totalCount}건 (선택: {selectedRowKeys.length}건)
                        </div>
                        <div className="flex gap-2">
                            <Button type="primary" onClick={() => handleAdd()}>
                                신규 생성
                            </Button>
                            <Button
                                danger
                                disabled={selectedRowKeys.length === 0}
                                onClick={() => {
                                    Modal.confirm({
                                        title: '선택 삭제',
                                        content: `선택된 ${selectedRowKeys.length}건의 용어사전을 삭제하시겠습니까?`,
                                        okText: '확인',
                                        cancelText: '취소',
                                        onOk: () => handleDelete()
                                    })
                                }}
                            >
                                선택 삭제 ({selectedRowKeys.length})
                            </Button>
                        </div>
                    </div>

                    <DictionaryManageTable
                        data={dictionaries.items}
                        loading={loading}
                        selectedRowKeys={selectedRowKeys}
                        onSelectionChange={setSelectedRowKeys}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onItemClick={handleItemClick}
                        currentPage={currentPage}
                        pageSize={pageSize}
                        totalCount={totalCount}
                        onPageChange={handlePageChange}
                    />
                </div>
            </div>

            {/* 사이드 패널 (상세 정보) */}
            {selectedItem && <DictionaryPreviewPanel item={selectedItem} onClose={handleCloseDetail} />}
        </div>
    )
}

