 11→    onClose: () => void
 12→    onSubmit: (values: DictionaryFormValues, item?: DictionaryItem) => Promise<void>
 13→    item?: DictionaryItem
 14→}
 15→
 16→export const DictionaryManageFormModal: FC<DictionaryManageFormModalProps> = ({ open, onClose, onSubmit, item }) => {
 17→    const [form] = Form.useForm<DictionaryFormValues>()
 18→    const editorRef = useRef<EditorRef>(null)
 19→
 20→    useEffect(() => {
 21→        if (item) {
 22→            // 수정 모드
 23→            form.setFieldsValue({
 24→                name: item.name,
 25→                number: item.number
 26→            })
 27→            // Editor에 초기 content 세팅
 28→            editorRef.current?.setContent(item.description || '')
 29→        } else {
 30→            // 생성 모드
 31→            form.resetFields()
 32→            editorRef.current?.setContent('')
 33→        }
 34→    }, [item])
 35→
 36→    const handleSubmit = async () => {
 37→        try {
 38→            const values = await form.validateFields()
 39→
 40→            // Editor에서 직접 content를 읽어옴
 41→            const editorContent = editorRef.current?.getContent() || ''
 42→
 43→            // danawa.com 또는 enuri.com 포함 URL 패턴 검사
 44→            const forbiddenPatterns = [/danawa\.com/i, /enuri\.com/i]
 45→            for (const pattern of forbiddenPatterns) {
 46→                if (pattern.test(editorContent)) {
 47→                    throw new Error('danawa.com 및 enuri.com 도메인 URL은 사용할 수 없습니다')
 48→                }
 49→            }
 50→
 51→            // description이 빈 HTML인 경우 빈 문자열로 변환
 52→            const text = getTextFromHtml(editorContent)
 53→            const description = text.length === 0 ? '' : editorContent
 54→
 55→            await onSubmit(
 56→                {
 57→                    ...values,
 58→                    description
 59→                },
 60→                item
 61→            )
 62→
 63→            // 성공 시 모달 닫기
 64→            onClose()
 65→        } catch (error) {
 66→            // 에러 메시지 표시
 67→            if (error instanceof Error) {
 68→                message.error(error.message)
 69→            }
 70→        }
 71→    }
 72→
 73→    const handleClose = () => {
 74→        form.resetFields()
 75→        onClose()
 76→    }
 77→
 78→    return (
 79→        <Modal
 80→            title={item ? '용어 수정' : '용어 등록'}
 81→            open={open}
 82→            onCancel={handleClose}
 83→            onOk={handleSubmit}
 84→            destroyOnClose
 85→            width={800}
 86→            cancelText="취소"
 87→            okText={item ? '수정' : '등록'}
 88→        >
 89→            <Form form={form} layout="vertical" className="p-6">
 90→                <Form.Item
 91→                    name="name"
 92→                    label="용어명"
 93→                    required
 94→                    rules={[{ required: true, message: '용어명을 입력해주세요' }]}
 95→                >
